from google.cloud import logging_v2
from google.cloud.logging_v2.resource import Resource

class ObservabilityClient:
    def __init__(self, project_id: str, log_name: str):
        self.project_id = project_id
        self.log_name = log_name
        self.client = logging_v2.Client(project=self.project_id)
        self.logger = self.client.logger(self.log_name)

    def write_log_entry(self, payload: dict, severity: str = "INFO", resource_type: str = "global", labels: dict = None):
        if labels is None:
            labels = {"project_id": self.project_id}

        # Google Cloud Logging expects 'jsonPayload' for structured logs
        # The `log_struct` method handles this automatically.
        self.logger.log_struct(
            payload,
            severity=severity,
            resource=Resource(type=resource_type, labels=labels),
        )
        return {"submitted": True}

    def list_log_entries(self, filter_expression: str, order_by: str = "timestamp desc", page_size: int = 100):
        entries = self.client.list_entries(
            filter_=filter_expression,
            order_by=order_by,
            page_size=page_size,
            project_ids=[self.project_id]
        )
        # Iterate over entries to retrieve all pages
        return [entry for entry in entries]

from dataclasses import dataclass, field
from datetime import datetime
from typing import Any, Dict, Optional

@dataclass
class LogEntry:
    log_name: str
    resource_type: str
    resource_labels: Dict[str, str]
    timestamp: datetime
    severity: str
    json_payload: Optional[Dict[str, Any]] = field(default_factory=dict)
    text_payload: Optional[str] = None
    insert_id: Optional[str] = None
    trace: Optional[str] = None
    span_id: Optional[str] = None
    receive_timestamp: Optional[datetime] = None

@dataclass
class QueryFilter:
    project_id: str
    log_name: Optional[str] = None
    severity: Optional[str] = None
    time_range_start: Optional[datetime] = None
    time_range_end: Optional[datetime] = None
    free_text_search: Optional[str] = None
    correlation_id: Optional[str] = None

    def to_filter_string(self) -> str:
        filters = [f"project="{self.project_id}""]
        if self.log_name:
            filters.append(f"logName="projects/{self.project_id}/logs/{self.log_name}"")
        if self.severity:
            filters.append(f"severity>="{self.severity}"")
        if self.time_range_start:
            filters.append(f"timestamp>="{self.time_range_start.isoformat()}Z"")
        if self.time_range_end:
            filters.append(f"timestamp<="{self.time_range_end.isoformat()}Z"")
        if self.free_text_search:
            filters.append(f"text:("{self.free_text_search}"")")
        if self.correlation_id:
            filters.append(f"jsonPayload.correlationId="{self.correlation_id}"")
        return " AND ".join(filters)

from google.cloud import translate_v3 as translate

def translate_log_message(project_id: str, log_message: str, target_language_code: str) -> str:
    client = translate.TranslationServiceClient()

    parent = f"projects/{project_id}/locations/global"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [log_message],
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text

    return translated_text
